<script setup lang="ts">
import {ref,watch} from 'vue'
import {usePayrollPage} from '../payrollPage'
import PhaseStatus from './PhaseStatus.vue'
interface Record {id:string;employeeId:string;employeeName:string;originMonth:string;settlementMonth:string;status:string;originalBatchId:string|null;gross:string|null;employeeCpf:string|null;cdac:string|null;net:string|null;employerCpfDelta:string|null;sdlDelta:string|null}
interface Summary {companyId:string;month:string;asOf:string;ordinaryAvailable:boolean;employeeCount:number;ordinaryGross:string|null;ordinaryNet:string|null;supplementalGross:string|null;supplementalNet:string|null;formalGross:string|null;formalNet:string|null;records:Record[];segments?:{id:string;employeeId:string;employeeName:string;from:string;cutoff:string;gross:string;net:string}[]}
const props=defineProps<{companyId:string;month:string}>(),{api,base,load,loading,failure,english,format}=usePayrollPage(),data=ref<Summary|null>(null),x=(z:string,e:string)=>english()?e:z,money=(v:string|null)=>v??'—'
watch(()=>[props.companyId,props.month],()=>{data.value=null;const company=props.companyId,month=props.month;if(!company||!/^\d{4}-(0[1-9]|1[0-2])$/.test(month))return;void load(()=>api().get<Summary>('/supplemental-month-summary?'+new URLSearchParams({companyId:company,month})),v=>{if(company!==props.companyId||month!==props.month)return;if(v.companyId!==company||v.month!==month||!Array.isArray(v.records))throw new Error('Summary scope mismatch');data.value=v})},{immediate:true})
</script>
<template><section class="wf-section"><h3>{{x('所属期正式工资与补发对账','Original-period formal payroll and supplements')}}</h3><PhaseStatus :loading="loading" :failure="failure"/><template v-if="data"><p class="wf-hint">{{month}} · {{x('补充汇总时点','Supplemental summary as of')}} {{format(data.asOf,'Asia/Singapore')}} · {{x('已正式结算人数（去重）','Distinct formally settled employees')}} {{data.employeeCount}}</p><div class="wf-table-wrap"><table><thead><tr><th>{{x('口径','Scope')}}</th><th>{{x('应发','Gross')}}</th><th>{{x('应实发','Net payable')}}</th></tr></thead><tbody><tr><td>{{data.segments?.length?x('普通工资＋已正式独立结薪','Ordinary + independent formal wages'):x('原正式普通工资','Original formal payroll')}}</td><td>{{money(data.ordinaryGross)}}</td><td>{{money(data.ordinaryNet)}}</td></tr><tr><td>{{x('已确认个人补发','Confirmed supplements')}}</td><td>{{money(data.supplementalGross)}}</td><td>{{money(data.supplementalNet)}}</td></tr><tr><th>{{x('所属期补充汇总','Original-period updated summary')}}</th><td>{{money(data.formalGross)}}</td><td>{{money(data.formalNet)}}</td></tr></tbody></table></div><p v-if="!data.ordinaryAvailable" role="status">{{x('原普通工资未形成完整正式结果，全量正式金额尚不可得；补发小计仍单独列示。','Original ordinary payroll is incomplete. Full formal totals are unavailable; supplements remain separately visible.')}}</p><p class="wf-hint">{{x('原冻结工资与原报表保持不变；此处按所属期补充归集。补发已确认不代表已付款；跨月付款不重复计作工资收入。','Original frozen payroll and reports remain unchanged. This is a supplementary original-period summary. Confirmed supplements are not paid automatically; payment in another month does not create income again.')}}</p><section v-if="data.segments?.length" class="wf-section"><h4>{{x('独立结薪覆盖范围','Independent settlement coverage')}}</h4><p v-for="s in data.segments" :key="s.id">{{s.employeeName}} · {{s.from}} – {{s.cutoff}} · SGD {{s.net}} <RouterLink :to="{path:base+'/payroll-segments',query:{companyId,month,segmentId:s.id}}">{{x('结薪与付款','Settlement and payments')}}</RouterLink></p><p class="wf-hint">{{x('此处为已正式金额；后续未结期间另行办理，不表示整月已结清。','These are formal amounts to date; later unpaid ranges are settled separately.')}}</p></section><div v-if="data.records.length" class="wf-table-wrap"><table><thead><tr><th>{{x('员工','Employee')}}</th><th>{{x('所属月 / 结算月','Origin / settlement month')}}</th><th>{{x('补发收入','Supplemental income')}}</th><th>{{x('员工 CPF / CDAC','Employee CPF / CDAC')}}</th><th>{{x('本次应实发','Net payable this time')}}</th><th></th></tr></thead><tbody><tr v-for="record in data.records" :key="record.id"><td>{{record.employeeName}}</td><td>{{record.originMonth}} / {{record.settlementMonth}}</td><td>{{money(record.gross)}}</td><td>{{money(record.employeeCpf)}} / {{money(record.cdac)}}</td><td>{{money(record.net)}}</td><td><RouterLink :to="{path:base+'/supplemental-payroll',query:{companyId,employeeId:record.employeeId,originMonth:month,batchId:record.id}}">{{x('查看补发及付款','Supplement and payments')}}</RouterLink><details><summary>{{x('公司法定调整','Employer statutory adjustments')}}</summary><p>CPF {{money(record.employerCpfDelta)}} · SDL {{money(record.sdlDelta)}}</p><p class="wf-hint">{{x('可能涉及跨期责任调整，不直接当作本期公司成本合计。','May include liabilities for other periods; not a current-period company cost total.')}}</p></details></td></tr></tbody></table></div></template></section></template>
